import clsx from 'clsx';
import React, { KeyboardEvent, PropsWithChildren, useMemo } from 'react';
import { toast } from 'react-toastify';

import {
  InformationIcon,
  SuccessIcon,
  WarningIcon,
} from '@dynatrace/strato-icons';

import {
  toastCSS,
  toastFlexContainerCSS,
  toastIconCSS,
  toastTextCSS,
} from './Toast.sty.js';
import type { ToastPosition } from './ToastPosition.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';
import { Text } from '../../typography/Text.js';

type ToastProps = PropsWithChildren<{
  type: 'info' | 'warning' | 'critical' | 'success';
  title: string;
  message?: string | JSX.Element;
  closeToast: () => void;
}> &
  StylingProps &
  DataTestId;

const Toast = (props: ToastProps) => {
  const {
    children,
    type,
    title,
    message,
    closeToast,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  const Icon = useMemo(() => {
    switch (type) {
      case 'warning':
        return <WarningIcon />;
      case 'success':
        return <SuccessIcon />;
      case 'critical':
      case 'info':
        return <InformationIcon />;
    }
  }, [type]);

  // Handle the escape key
  const closeToastOnEsc = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      closeToast();
    }
  };

  return (
    <div
      data-testid={dataTestId}
      className={clsx(consumerClassName, toastCSS)}
      style={consumerStyle}
      onKeyDown={closeToastOnEsc}
    >
      <div className={toastIconCSS({ variant: type })}>{Icon}</div>
      <Flex
        className={clsx(
          toastFlexContainerCSS,
          textStyleCSS({ textStyle: 'base' }),
        )}
        paddingLeft={16}
        paddingTop={12}
        paddingBottom={12}
        paddingRight={8}
        flexDirection="column"
        alignItems="flex-start"
        flexGrow={1}
        gap={6}
      >
        {title && (
          <Text className={toastTextCSS} textStyle="base-emphasized" as="p">
            {title}
          </Text>
        )}
        {message && (
          <Text className={toastTextCSS} textStyle="base" as="p">
            {message}
          </Text>
        )}
        {children}
      </Flex>
    </div>
  );
};

// #region Typings
/** Options that can be given to the showToast function. */
export interface ToastOptions extends StylingProps, DataTestId {
  /** A unique id for the toast. Using this toast id consumer can control
   *  the behavior of individual toast notifications.  Toast messages with same
   *  id will only be shown once.
   */
  id?: string | number;

  /** Title displayed in the toast notification. */
  title: string;
  /**
   * Type of the notification. Also indicates the color and icon.
   * @defaultValue 'info'
   * */
  type?: 'info' | 'warning' | 'critical' | 'success';
  /** Message displayed in the toast notification. */
  message?: string | JSX.Element;
  /**
   * The Toast notification will automatically close after a certain period of
   * time given in milliseconds. If 'infinite' is provided, the consumer will
   * need to manually close the toast.
   * Default value by type:
   * info: 8000ms
   * critical and warning: 'infinite'
   * */
  lifespan?: number | 'infinite';
  /**
   * Optional actions passed to the toast element, appended on the bottom left.
   * Should only be used to either add a Button or a Link.
   */
  actions?: JSX.Element;
  /**
   * Live region roles
   * * Default value by type:
   * info and warning: 'status'
   * critical: 'alert'
   */
  role?: 'alert' | 'log' | 'status';
  /**
   * Position of toast
   * @defaultValue 'bottom-left'
   */
  position?: ToastPosition;
}
// #endregion Typings

/**
 * Function to open a toast configuration.
 *
 * @returns the respective toast id
 */
export function showToast({
  id,
  type = 'info',
  title,
  message,
  role,
  position = 'bottom-left',
  className: consumerClassName,
  style: consumerStyle,
  'data-testid': dataTestId,
  ...remainingOptions
}: ToastOptions): number | string {
  // Merge passed options with defaults provided by type
  const options = {
    lifespan: type === 'info' || type === 'success' ? 8000 : 'infinite',
    ...remainingOptions,
  };

  return toast(
    <Toast
      type={type}
      title={title}
      message={message}
      closeToast={() => undefined}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {options.actions}
    </Toast>,
    {
      toastId: id,
      autoClose:
        typeof options.lifespan === 'string' ? false : options.lifespan,
      role: role,
      position,
    },
  );
}

/**
 * Function to close a single toast.
 *
 * @param id - id of the toast that should be dismissed
 */
export function dismissToast(id: string | number): void {
  toast.dismiss(id);
}

/**
 * Function to close all open toasts at once.
 */
export function dismissAllToasts(): void {
  toast.dismiss();
}
